# Official Knowledge Guide: Case Status Complete Guide

## Topic
Court Case Status, Orders & Judgments Retrieval System

## Portals
[
  {
    "name": "eCourts Services Portal (District & High Courts)",
    "url": "https://services.ecourts.gov.in/ecourtindia_v6/"
  },
  {
    "name": "eCourts Single Sign-On Portal",
    "url": "https://ecourts.gov.in"
  },
  {
    "name": "Supreme Court of India Case Status Portal",
    "url": "https://www.sci.gov.in/case-status/"
  },
  {
    "name": "National Judicial Judgments Search Portal",
    "url": "https://judgments.ecourts.gov.in"
  }
]

## Search Methods
[
  {
    "method": "CNR Number Search",
    "description": "Case Natural Record (CNR) is a unique 16-character alphanumeric number assigned to every court case across India.",
    "format_breakdown": {
      "example": "MHAU010000012022",
      "characters_1_2": "State Code (e.g., MH for Maharashtra, DL for Delhi, UP for Uttar Pradesh)",
      "characters_3_4": "District / Establishment Code (e.g., AU for Aurangabad, HC for High Court)",
      "characters_5_12": "Unique 6-digit Court and Case Establishment Number",
      "characters_13_16": "4-digit Year of Filing (e.g., 2022)"
    },
    "procedure": [
      "Visit https://services.ecourts.gov.in or open eCourts Services Mobile App",
      "Select 'Search by CNR Number'",
      "Enter 16-character alphanumeric CNR without hyphens or spaces",
      "Enter Captcha and click 'Search'",
      "Complete Case History, Order Sheets, Next Hearing Date, and Judge details are displayed"
    ]
  },
  {
    "method": "Case Number Search",
    "procedure": [
      "Select State, District, and Court Complex",
      "Select Case Type from dropdown (e.g., Civil Suit, Criminal Appeal, Writ Petition, Bail Application)",
      "Enter Case Number (up to 7 digits)",
      "Enter 4-digit Year of registration (YYYY)",
      "Enter Captcha and Submit"
    ]
  },
  {
    "method": "Party Name Search",
    "procedure": [
      "Select State and Court Complex",
      "Enter Petitioner or Respondent Name (minimum 3 characters)",
      "Enter Registration Year (or leave blank to search all years)",
      "Select Status: 'Pending', 'Disposed', or 'Both'",
      "Submit to view list of matching cases"
    ]
  },
  {
    "method": "Advocate Name Search",
    "procedure": [
      "Select Court Complex",
      "Enter Advocate's full name or Bar Council Enrollment Number",
      "Select Pending or Disposed",
      "Submit to display active caseload and cause lists for the advocate"
    ]
  },
  {
    "method": "FIR Number Search",
    "procedure": [
      "Select Court Complex",
      "Select Police Station from dropdown",
      "Enter FIR Number",
      "Enter FIR Year",
      "Submit to retrieve the corresponding criminal trial or remand proceedings"
    ]
  },
  {
    "method": "Act and Section Search",
    "procedure": [
      "Select Court Complex",
      "Select Act Name from list (e.g., Indian Penal Code, Negotiable Instruments Act, POCSO Act)",
      "Enter specific Section number (e.g., Section 138, Section 302)",
      "Submit to filter cases registered under that specific statutory provision"
    ]
  }
]

## Downloading Orders And Judgments
{
  "interim_orders": "In the case details window, scroll to 'History of Case Hearing' or 'Business on Date'. Each hearing date with an order contains a clickable PDF icon. Clicking this icon opens or downloads the scanned / digitally signed daily order sheet.",
  "final_judgments": "On case disposal, the final judgment is uploaded under the 'Orders / Judgment' tab. Click the Judgment PDF link to view or download.",
  "certified_copies": "For legal enforcement or appeal, certified physical or digitally watermarked copies must be requested via the online e-Certified Copy portal (or e-Sewa Kendra at the court complex) upon payment of statutory copying fees.",
  "free_judgment_portal": "https://judgments.ecourts.gov.in provides free full-text keyword search across millions of High Court and Supreme Court judgments using neutral citations and Indian language translations."
}

## Sms Pull Service
{
  "number": "9766899899",
  "format": "SMS ECOURTS <space> <16-digit CNR Number>",
  "response": "Returns an automated SMS containing current case status, next hearing date, and court name."
}

