    "portal": "Official YouTube Channel",
    "url": "https://www.youtube.com/@HighCourtofKarnatakaLive"
  },
  {
    "court": "High Court of Madhya Pradesh",
    "portal": "Official Portal & YouTube",
    "url": "https://mphc.gov.in"
  },
  {
    "court": "High Court of Orissa",
    "portal": "Official YouTube Channel",
    "url": "https://www.youtube.com/@HighCourtofOrissaLive"
  },
  {
